const form = document.querySelector("#langganan");
const pesan = document.querySelector("#pesan");
function emailValid(email) {
  return email.includes("@") && email.includes(".");
}
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const email = form.elements.email.value.trim();
  if (!emailValid(email)) {
    pesan.textContent = "Email belum benar";
    return;
  }
  pesan.textContent = `Terima kasih, ${email} terdaftar`;
});
form.elements.email.value = "budi.mail.com";
form.requestSubmit();
console.log(pesan.textContent);
form.elements.email.value = "  budi@mail.com ";
form.requestSubmit();
console.log(pesan.textContent);

