const form = document.querySelector("#daftar");
const pesan = document.querySelector("#pesan");
function validasi(data) {
  if (data.username.length < 4) return "Username minimal 4 karakter";
  if (data.sandi.length < 8) return "Sandi minimal 8 karakter";
  return "";
}
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const error = validasi(Object.fromEntries(new FormData(form)));
  pesan.textContent = error || "Pendaftaran berhasil";
});
function kirim(username, sandi) {
  form.elements.username.value = username;
  form.elements.sandi.value = sandi;
  form.requestSubmit();
  console.log(pesan.textContent);
}
kirim("bo", "rahasia123");
kirim("budi", "123");
